function e(e){document.getElementById(`feedbackForm`).action=`/buyer/orders/`+e+`/feedback`,document.getElementById(`ratingInput`).value=``,document.querySelectorAll(`.star`).forEach(e=>e.classList.remove(`active`)),document.getElementById(`feedbackModal`).classList.add(`open`)}function t(e){document.getElementById(`ratingInput`).value=e,document.querySelectorAll(`.star`).forEach(t=>{t.classList.toggle(`active`,parseInt(t.dataset.val)<=e)})}document.getElementById(`feedbackModal`).addEventListener(`click`,e=>{e.target===document.getElementById(`feedbackModal`)&&document.getElementById(`feedbackModal`).classList.remove(`open`)}),window.openFeedback=e,window.setRating=t;